import Foundation
func validatedSupplies(_ values: [Supply]) throws -> [Supply] {
    var seen: Set<Int> = []
    for value in values {
        let title = value.title.trimmingCharacters(in: .whitespacesAndNewlines)
        guard value.id > 0, value.count >= 0, !title.isEmpty,
              seen.insert(value.id).inserted else {
            throw SupplyError.invalidData
        }
    }
    return values
}
