    _ = try validatedSupplies([Supply(id: 11, title: "Чай", count: 2),
                              Supply(id: 11, title: "Крупа", count: 1)])
    assertionFailure("Ожидался отказ дубля")
} catch { assert(error as? SupplyError == .invalidData) }
do {
    _ = try validatedSupplies([Supply(id: 12, title: "Крупа", count: -1)])
    assertionFailure("Ожидался отказ количества")
} catch { assert(error as? SupplyError == .invalidData) }

Проверка выполняется до записи; trim служит условию непустого title, но не меняет сохранённый пользовательский текст.

actor SupplyRepository {
    private let cache: any SupplyCache
    private let remote: any SupplyRemote
    private var generation = 0
    init(cache: any SupplyCache, remote: any SupplyRemote) {
        self.cache = cache
        self.remote = remote
    }
    func cached() throws -> [Supply] { try validatedSupplies(cache.load()) }
    func refresh() async throws -> [Supply] {
        generation += 1
        let request = generation
        try Task.checkCancellation()
        let values = try await remote.fetch()
        try Task.checkCancellation()
        guard request == generation else { throw SupplyError.stale }
        let candidate = try validatedSupplies(values)
        try cache.save(candidate)
        return candidate
    }
}
