import Observation
@MainActor @Observable
final class SupplyModel {
    private(set) var state = SupplyState()
    private let repository: SupplyRepository
    private var generation = 0
    init(repository: SupplyRepository) { self.repository = repository }
    func refresh() async {
        generation += 1
        let request = generation
        var readCache = false
        state.isLoading = true
        state.error = nil
        do {
            let cached = try await repository.cached()
            guard request == generation else { return }
            try Task.checkCancellation()
            state.items = cached
            state.isStale = true
            readCache = true
            let fresh = try await repository.refresh()
            guard request == generation else { return }
            try Task.checkCancellation()
            state.items = fresh
            state.isStale = false
            state.isLoading = false
        } catch is CancellationError {
            guard request == generation else { return }
            state.isLoading = false
        } catch {
            guard request == generation else { return }
            state.isLoading = false
            state.isStale = true
            state.error = readCache ? "Не удалось обновить список" :
                "Не удалось прочитать сохранённые данные"
        }
    }
}

SupplyModel не кодирует JSON и не делает transport. Каждый await отделён проверкой актуальности до применения результата; отмена завершает текущую загрузку без ошибки.

