final class FeatureTests: XCTestCase {
    @MainActor func testOfflineRestart() async throws {
        let file = try newTestFile()
        defer {
            let folder = file.deletingLastPathComponent()
            try? FileManager.default.removeItem(at: folder)
        }
        let old = [Supply(id: 11, title: "Чай", count: 2)]
        try JSONSupplyCache(file: file).save(old)
        let model = makeSupplyFeature(file: file, remote: FailingSupplyRemote())
        await model.refresh()
        XCTAssertEqual(model.state.items, old)
        XCTAssertTrue(model.state.isStale)
        XCTAssertFalse(model.state.isLoading)
        XCTAssertEqual(model.state.error, "Не удалось обновить список")
    }
}

